&lt;div class=&quot;flex h-svh w-screen flex-col&quot;&gt;
&lt;div class=&quot;relative z-0 flex min-h-0 w-full flex-1&quot;&gt;
&lt;div class=&quot;relative flex min-h-0 w-full flex-1&quot;&gt;&amp;nbsp;&lt;/div&gt;
&lt;/div&gt;
&lt;div&gt;
&lt;div class=&quot;flex h-svh w-screen flex-col&quot;&gt;
&lt;div class=&quot;relative z-0 flex min-h-0 w-full flex-1&quot;&gt;
&lt;div class=&quot;relative flex min-h-0 w-full flex-1&quot;&gt;&amp;nbsp;&lt;/div&gt;
